    typia.assertGuard(updatedChildWithParent.parentDepartment!);
    TestValidator.equals(
      "parent ID matches",
      updatedChildWithParent.parentDepartment.id,
      parentDepartment.id,
    );
    TestValidator.equals(
      "parent name matches",
      updatedChildWithParent.parentDepartment.name,
      parentDepartment.name,
