  // 4. Create departments for potential employee assignment
  const department1 =
    await generate_random_hrm_platform_member_departments_create(
      memberConnection,
      {
        body: {
          name: `Engineering-${RandomGenerator.alphabets(5)}`,
          description: "Engineering department",
