  // 10. Test filtering by new_status = "closed"
  const historyToClosed =
    await api.functional.hrmPlatform.member.projects.tasks.histories.index(
      memberConnection,
      {
        projectId: project.id,
        taskId: task.id,
        body: {
          new_status: "closed",
          sort: "created_at_asc",
          page: 1,
          limit: 100,
