  // === SUB-CASE 3: Remove task from timer (task2 -> null) ===
  const timerWithoutTask =
    await api.functional.hrmPlatform.member.timers.putByTimerid(
      memberConnection,
      {
        timerId: timer.id,
        body: {
          task_id: null,
