export async function putHrmPlatformMemberTimelogsTimelogId(props: {
  member: MemberPayload;
  timelogId: string & tags.Format<"uuid">;
  body: IHrmPlatformTimelog.IUpdate;
}): Promise<IHrmPlatformTimelog> {
  const timelog = await MyGlobal.prisma.hrm_platform_timelogs.findUniqueOrThrow(
    {
      where: { id: props.timelogId, deleted_at: null },
      select: {
        id: true,
        employee_id: true,
        timesheet_id: true,
        timesheet: { select: { status: true } },
      },
    },
  );
  if (
    timelog.timesheet_id !== null &&
    timelog.timesheet?.status === "approved"
  ) {
    throw new HttpException("Cannot update timelog in approved timesheet", 422);
  }
  const employee =
    await MyGlobal.prisma.hrm_platform_employees.findFirstOrThrow({
      where: { user_id: props.member.id, deleted_at: null },
      select: { id: true, role_id: true, organization_id: true },
    });
  const isOwner = timelog.employee_id === employee.id;
  if (!isOwner) {
    const hasTimeManagePermission =
      await MyGlobal.prisma.hrm_platform_role_permissions.findFirst({
        where: {
          hrm_platform_role_id: employee.role_id,
          permission: "time:manage",
          deleted_at: null,
        },
      });
    if (!hasTimeManagePermission) {
      throw new HttpException("Forbidden", 403);
    }
  }
  if (props.body.project_id !== undefined) {
    const projectMembership =
      await MyGlobal.prisma.hrm_platform_project_members.findFirst({
        where: {
          hrm_platform_employee_id: employee.id,
          hrm_platform_project_id: props.body.project_id,
          deleted_at: null,
        },
      });
    if (!projectMembership) {
      throw new HttpException("Employee is not assigned to this project", 400);
    }
    if (props.body.task_id !== undefined && props.body.task_id !== null) {
      const task = await MyGlobal.prisma.hrm_platform_tasks.findUnique({
        where: { id: props.body.task_id },
        select: { hrm_platform_project_id: true },
      });
      if (!task || task.hrm_platform_project_id !== props.body.project_id) {
        throw new HttpException(
          "Task does not belong to the specified project",
          400,
        );
      }
    }
  }
  const updated = await MyGlobal.prisma.hrm_platform_timelogs.update({
    where: { id: props.timelogId },
    data: {
      ...(props.body.date !== undefined && { date: new Date(props.body.date) }),
      ...(props.body.duration_minutes !== undefined && {
        duration_minutes: props.body.duration_minutes,
      }),
      ...(props.body.project_id !== undefined && {
        project_id: props.body.project_id,
      }),
      ...(props.body.task_id !== undefined && { task_id: props.body.task_id }),
      ...(props.body.description !== undefined && {
        description: props.body.description,
      }),
      ...(props.body.billable !== undefined && {
        billable: props.body.billable,
      }),
      updated_at: new Date(),
    },
    ...HrmPlatformTimelogTransformer.select(),
  });
  return await HrmPlatformTimelogTransformer.transform(updated);
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { MemberPayload } from "../decorators/payload/MemberPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function deleteHrmPlatformMemberProjectsProjectIdTasksTaskId(props: {
  member: MemberPayload;
  projectId: string & tags.Format<"uuid">;
  taskId: string & tags.Format<"uuid">;
}): Promise<void> {
  // Resolve member to employee record to check project membership and role
  const employee =
    await MyGlobal.prisma.hrm_platform_employees.findFirstOrThrow({
      where: {
        user_id: props.member.id,
        deleted_at: null,
      },
      select: {
        id: true,
        role_id: true,
      },
    });
  // Check if user is project lead for this project
  const projectMembership =
    await MyGlobal.prisma.hrm_platform_project_members.findFirst({
      where: {
        hrm_platform_employee_id: employee.id,
        hrm_platform_project_id: props.projectId,
        deleted_at: null,
      },
    });
  // Get employee's role to check for project:manage permission
  const role = await MyGlobal.prisma.hrm_platform_roles.findUnique({
    where: { id: employee.role_id },
    select: {
      id: true,
      rolePermissions: {
        select: { permission: true },
      },
    },
  });
  // Check permission: project:manage OR project-lead role
  const hasProjectManagePermission = role?.rolePermissions.some(
    (p: { permission: string }) => p.permission === "project:manage",
  );
  const isProjectLead = projectMembership?.role === "project-lead";
  if (!hasProjectManagePermission && !isProjectLead) {
    throw new HttpException(
      "Forbidden: Requires project:manage permission or project-lead role",
      403,
    );
  }
  // Verify task exists, belongs to project, and is not already deleted
  const task = await MyGlobal.prisma.hrm_platform_tasks.findUniqueOrThrow({
    where: { id: props.taskId },
    select: {
      id: true,
      hrm_platform_project_id: true,
      deleted_at: true,
    },
  });
  if (task.hrm_platform_project_id !== props.projectId) {
    throw new HttpException("Task does not belong to specified project", 400);
  }
  if (task.deleted_at !== null) {
    throw new HttpException("Task is already deleted", 400);
  }
  // Soft delete task (cascade handles subtasks via DB onDelete: Cascade)
  await MyGlobal.prisma.hrm_platform_tasks.update({
    where: { id: props.taskId },
    data: {
      deleted_at: new Date(),
    },
  });
  // Get organization ID from project for activity log
  const project = await MyGlobal.prisma.hrm_platform_projects.findUniqueOrThrow(
    {
      where: { id: props.projectId },
      select: { organization_id: true },
    },
  );
  // Record deletion in activity log
  await MyGlobal.prisma.hrm_platform_activity_logs.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      organization_id: project.organization_id,
      member_id: props.member.id,
      action_type: "task.deleted",
      target_entity_type: "task",
      target_entity_id: props.taskId,
      created_at: new Date(),
      updated_at: new Date(),
    },
  });
}

