    where: whereInput,
  });
  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    } satisfies IPage.IPagination,
    data: data.map(
      (member) =>
        ({
          id: member.id,
          role: member.role,
          employee: {
            id: member.employee.id,
            user: {
