import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { MemberPayload } from "../decorators/payload/MemberPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function deleteHrmPlatformMemberOrganizationsOrganizationId(props: {
  member: MemberPayload;
  organizationId: string & tags.Format<"uuid">;
}): Promise<void> {
  // Verify organization exists and is not already deleted
  const organization =
    await MyGlobal.prisma.hrm_platform_organizations.findUnique({
      where: {
        id: props.organizationId,
        deleted_at: null,
      },
    });
  if (!organization) {
    throw new HttpException("Not Found", 404);
  }
  // Find the Owner role for this organization
  const ownerRole = await MyGlobal.prisma.hrm_platform_roles.findFirst({
    where: {
      organization_id: props.organizationId,
      name: "Owner",
      is_builtin: true,
      deleted_at: null,
    },
  });
  if (!ownerRole) {
    throw new HttpException("Not Found", 404);
  }
  // Verify the member is the owner (has employee record with Owner role)
  const employee = await MyGlobal.prisma.hrm_platform_employees.findFirst({
    where: {
      organization_id: props.organizationId,
      user_id: props.member.id,
      role_id: ownerRole.id,
      deleted_at: null,
    },
  });
  if (!employee) {
    throw new HttpException("Forbidden", 403);
  }
  // Check for pending timesheets (draft or submitted status)
  const pendingTimesheets =
    await MyGlobal.prisma.hrm_platform_timesheets.findFirst({
      where: {
        employee: {
          organization_id: props.organizationId,
        },
        status: {
          in: ["draft", "submitted"],
        },
        deleted_at: null,
      },
    });
  if (pendingTimesheets) {
    throw new HttpException(
      "Conflict: Pending timesheets must be resolved before deletion",
      409,
    );
  }
  // Check for active employee contracts (end_date is null or in the future)
  const activeContract =
    await MyGlobal.prisma.hrm_platform_employee_contracts.findFirst({
      where: {
        employee: {
          organization_id: props.organizationId,
        },
        OR: [{ end_date: null }, { end_date: { gt: new Date() } }],
        deleted_at: null,
      },
    });
  if (activeContract) {
    throw new HttpException(
      "Conflict: Active employee contracts must be ended before deletion",
      409,
    );
  }
  // Perform cascade deletion in transaction
  await MyGlobal.prisma.$transaction(async (tx) => {
    // Delete all projects (cascades to tasks, project_members, timelogs)
    await tx.hrm_platform_projects.deleteMany({
      where: {
        organization_id: props.organizationId,
      },
    });
    // Delete all timesheets
    await tx.hrm_platform_timesheets.deleteMany({
      where: {
        employee: {
          organization_id: props.organizationId,
        },
      },
    });
    // Delete all employee contracts
    await tx.hrm_platform_employee_contracts.deleteMany({
      where: {
        employee: {
          organization_id: props.organizationId,
        },
      },
    });
    // Delete all employees (cascades timelogs, timesheets)
    await tx.hrm_platform_employees.deleteMany({
      where: {
        organization_id: props.organizationId,
      },
    });
    // Delete all departments
    await tx.hrm_platform_departments.deleteMany({
      where: {
        organization_id: props.organizationId,
      },
    });
    // Delete all roles (custom and built-in)
    await tx.hrm_platform_roles.deleteMany({
      where: {
        organization_id: props.organizationId,
      },
    });
    // Delete all invitations
    await tx.hrm_platform_invitations.deleteMany({
      where: {
        organization_id: props.organizationId,
      },
    });
    // Soft delete the organization
    await tx.hrm_platform_organizations.update({
      where: {
        id: props.organizationId,
      },
      data: {
        deleted_at: new Date(),
      },
    });
  });
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IHrmPlatformDepartment } from "@ORGANIZATION/PROJECT-api/lib/structures/IHrmPlatformDepartment";
import { IHrmPlatformOrganization } from "@ORGANIZATION/PROJECT-api/lib/structures/IHrmPlatformOrganization";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { MemberPayload } from "../decorators/payload/MemberPayload";
import { HrmPlatformDepartmentTransformer } from "../transformers/HrmPlatformDepartmentTransformer";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function putHrmPlatformMemberDepartmentsDepartmentId(props: {
  member: MemberPayload;
  departmentId: string & tags.Format<"uuid">;
  body: IHrmPlatformDepartment.IUpdate;
}): Promise<IHrmPlatformDepartment> {
  const department =
    await MyGlobal.prisma.hrm_platform_departments.findUniqueOrThrow({
      where: { id: props.departmentId, deleted_at: null },
      select: { id: true, organization_id: true, name: true },
    });
  const employee =
    await MyGlobal.prisma.hrm_platform_employees.findFirstOrThrow({
      where: {
        user_id: props.member.id,
        organization_id: department.organization_id,
        deleted_at: null,
      },
      select: { id: true, role_id: true },
    });
  const permission =
    await MyGlobal.prisma.hrm_platform_role_permissions.findFirst({
      where: {
        hrm_platform_role_id: employee.role_id,
        permission: "org:manage",
        deleted_at: null,
      },
    });
  if (!permission) {
    throw new HttpException("Forbidden", 403);
  }
  if (props.body.name !== undefined) {
    const existingName =
      await MyGlobal.prisma.hrm_platform_departments.findFirst({
        where: {
          organization_id: department.organization_id,
          name: props.body.name,
          id: { not: props.departmentId },
          deleted_at: null,
        },
      });
    if (existingName) {
      throw new HttpException("Department name already exists", 409);
    }
  }
  if (props.body.parentDepartmentId !== undefined) {
    if (props.body.parentDepartmentId !== null) {
      const parent =
        await MyGlobal.prisma.hrm_platform_departments.findUniqueOrThrow({
          where: { id: props.body.parentDepartmentId, deleted_at: null },
          select: {
            id: true,
            organization_id: true,
            parent_department_id: true,
          },
        });
      if (parent.organization_id !== department.organization_id) {
        throw new HttpException(
          "Parent department must belong to same organization",
          400,
        );
      }
      if (parent.parent_department_id !== null) {
        throw new HttpException(
          "Cannot assign parent that already has a parent (one-level hierarchy)",
          400,
        );
      }
      if (parent.id === props.departmentId) {
        throw new HttpException("Cannot set department as its own parent", 400);
      }
      const isChild = await MyGlobal.prisma.hrm_platform_departments.findFirst({
        where: {
          parent_department_id: props.departmentId,
          id: props.body.parentDepartmentId,
          deleted_at: null,
        },
      });
      if (isChild) {
        throw new HttpException("Circular reference detected", 400);
      }
    }
  }
  const updateData: Prisma.hrm_platform_departmentsUpdateInput = {
    ...(props.body.name !== undefined && { name: props.body.name }),
    ...(props.body.description !== undefined && {
      description: props.body.description,
    }),
    ...(props.body.parentDepartmentId !== undefined && {
      parentDepartment: props.body.parentDepartmentId
        ? { connect: { id: props.body.parentDepartmentId } }
        : { disconnect: true },
    }),
    updated_at: new Date(),
  };
  await MyGlobal.prisma.hrm_platform_departments.update({
    where: { id: props.departmentId },
    data: updateData,
  });
  const updated =
    await MyGlobal.prisma.hrm_platform_departments.findUniqueOrThrow({
      where: { id: props.departmentId },
      ...HrmPlatformDepartmentTransformer.select(),
    });
  return await HrmPlatformDepartmentTransformer.transform(updated);
}

