  const existing =
    await MyGlobal.prisma.hrm_platform_role_permissions.findFirst({
      where: {
        hrm_platform_role_id: props.roleId,
        permission: props.body.permission,
        deleted_at: null,
      },
    });
  if (existing) {
    throw new HttpException("Permission already exists for this role", 409);
