import { TypedBody, TypedRoute } from "@nestia/core";
import { Controller, Ip } from "@nestjs/common";
import typia from "typia";

import { IHrmPlatformGuest } from "../../../../api/structures/IHrmPlatformGuest";
import { postHrmPlatformAuthGuestJoin } from "../../../../providers/postHrmPlatformAuthGuestJoin";
import { postHrmPlatformAuthGuestRefresh } from "../../../../providers/postHrmPlatformAuthGuestRefresh";

@Controller("/hrmPlatform/auth/guest")
export class HrmplatformAuthGuestController {
  /**
   * Register a new guest account for anonymous platform access using device fingerprint identification.
   *
   * This operation creates a temporary guest account in the hrm_platform_guests table with a unique device fingerprint. The device fingerprint serves as the primary identifier for recognizing returning guests without requiring email/password credentials. Upon successful registration, the system generates an initial guest session in hrm_platform_guest_sessions with JWT access and refresh tokens.
   *
   * The request must include a device_fingerprint string that uniquely identifies the client device. The system validates that this fingerprint is not already registered - attempting to join with an existing fingerprint returns a 409 Conflict error. Client metadata including IP address, current page URL (href), and referrer URL are captured from request headers and stored with the session for audit purposes.
   *
   * The response includes the newly created guest ID, access token for authenticated requests, refresh token for token renewal, and the session expiration timestamp. Guests can use these credentials to access guest-scoped endpoints until the session expires. The session expiration is automatically enforced by the database expired_at field.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Guest registration request with device fingerprint for unique identification.
   * @x-autobe-authorization-type join
   * @x-autobe-authorization-actor guest
   * @x-autobe-specification Create a new guest account identified by device fingerprint. Generate a unique guest ID and store the device fingerprint for future recognition. Create an initial guest session with JWT access and refresh tokens. Set session expiration based on configured timeout (e.g., 24 hours). Capture client metadata (IP, href, referrer) from request headers. Return the guest ID along with access token, refresh token, and expiration timestamp. Validate that device_fingerprint is provided and unique - return 409 Conflict if a guest with the same fingerprint already exists. The guest can use these tokens to access guest-scoped endpoints until session expiration.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("join")
  public async join(
    @Ip()
    ip: string,
    @TypedBody()
    body: IHrmPlatformGuest.IJoin,
  ): Promise<IHrmPlatformGuest.IAuthorized> {
    try {
      return await postHrmPlatformAuthGuestJoin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Renew an existing guest session by exchanging a refresh token for new access tokens.
   *
   * This operation validates the provided refresh token against the hrm_platform_guest_sessions table and generates new authentication tokens for continued guest access. The refresh token must correspond to an active, non-expired session in the database.
   *
   * The request requires a valid refresh token that was previously issued during guest join or a prior refresh operation. The system verifies the token exists in hrm_platform_guest_sessions, checks that the expired_at timestamp has not passed, and confirms the token has not been revoked. If validation fails, the operation returns 401 Unauthorized.
   *
   * Upon successful validation, the system generates a new access token and optionally a new refresh token for enhanced security. The session's expired_at field is updated to extend the session duration from the current time. The response includes the new access token, refresh token, and updated expiration timestamp. This allows guests to maintain continuous anonymous access without re-registering with their device fingerprint.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Guest session refresh request with refresh token for token renewal.
   * @x-autobe-authorization-type refresh
   * @x-autobe-authorization-actor guest
   * @x-autobe-specification Refresh an expired or expiring guest session token. Validate the provided refresh token against the hrm_platform_guest_sessions table. Check that the session exists, has not expired (expired_at > current time), and the refresh token matches. Generate a new access token and optionally a new refresh token. Update the session's expired_at timestamp to extend the session duration. Return the new tokens and updated expiration. Return 401 Unauthorized if the refresh token is invalid, expired, or not found. This allows guests to maintain their session without re-registering with device fingerprint.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("refresh")
  public async refresh(
    @TypedBody()
    body: IHrmPlatformGuest.IRefresh,
  ): Promise<IHrmPlatformGuest.IAuthorized> {
    try {
      return await postHrmPlatformAuthGuestRefresh({
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

